window.HUD_BUNDLE=["(function(root){\nfunction parseSheets(sheets){\n const result=[];\n for(const [sheet,rows] of Object.entries(sheets)){\n  const hi=rows.findIndex(r=>String(r[0]||'').trim().toLowerCase()==='item');\n  if(hi\u003c0)continue;\n  const headers=rows[hi];\n  for(const row of rows.slice(hi+1)){\n   const name=String(row[0]||'').trim();\n   if(!name)continue;\n   const points=[];let missing=0,invalid=0;\n   for(let c=1;c\u003cheaders.length;c++){\n    if(headers[c]==null||headers[c]==='')continue;\n    const raw=row[c];\n    if(raw==null||raw===''){missing++;continue;}\n    const v=typeof raw==='number'?raw:(typeof raw==='string'&&/^[+-]?(?:\\d+\\.?\\d*|\\.\\d+)(?:e[+-]?\\d+)?$/i.test(raw.trim())?Number(raw):NaN);\n    if(Number.isFinite(v))points.push({id:String(headers[c]),v});else invalid++;\n   }\n   if(!points.length)continue;\n   const unit=(name.match(/\\(([^()]*)\\)\\s*$/)||[])[1]||'';\n   let lo=null,hi=null,source='未提供客户限值',note='仅统计，待补充项目要求';\n   if(/Image Size/i.test(name)&&unit==='%'){lo=-5;hi=5;source='表内限值 ±5%';note='本表项目筛查；全局指标不能替代所有相邻网格点的 ±5% 验证';}\n   if(/Global Mag/i.test(name)&&unit==='%'){lo=95;hi=105;source='表内 global magnification ±5%';note='按 100% 为标称值，范围 95%～105%；请确认客户定义';}\n   if(/Rotation/i.test(name)&&unit==='°'){lo=-1;hi=1;source='表内限值 ±1°';note='当前为平均旋转，不能证明所有水平线段均满足 ±1°';}\n   if(/Ghost/i.test(name)&&unit==='mm'){let limit=sheet==='EB_N'?1:(sheet==='EB_H'||sheet==='EB_L'?1.5:null);if(limit!==null){lo=-limit;hi=limit;source='工作表重影限值 ±'+limit+' mm';note='按表内双向限值筛查。PDF 的 Tall 向下 / Short 向上为方向性要求；本表 Avg 不足以核验逐点最差重影、方向及三眼位最终判定';}}\n   result.push({key:sheet+'|'+name,sheet,name,unit,points,missing,invalid,lo,hi,source,note});\n  }\n }\n return result;\n}\nfunction stats(item){const a=item.points.map(p=>p.v),n=a.length,mean=a.reduce((s,x)=>s+x,0)/n,sd=n>1?Math.sqrt(a.reduce((s,x)=>s+(x-mean)**2,0)/(n-1)):0;const specified=item.lo!==null||item.hi!==null;const bad=item.points.filter(p=>(item.lo!==null&&p.v\u003citem.lo)||(item.hi!==null&&p.v>item.hi));return{n,mean,sd,min:Math.min(...a),max:Math.max(...a),specified,bad,pass:specified?(n-bad.length)/n:null};}\nfunction groupItems(items){\n const groups=new Map();\n for(const item of items){\n const name=item.name.replace(/_EBC/ig,'').replace(/_/g,' ').replace(/Buttom/ig,'Bottom').replace(/\\s+/g,' ').trim();\n const key=name.toLowerCase();\n if(!groups.has(key))groups.set(key,{key,name,unit:item.unit,primary:/ghost|rotation|image size/i.test(name),series:[]});\n groups.get(key).series.push(item);\n }\n return [...groups.values()];\n}\nroot.HUD={parseSheets,stats,groupItems};if(typeof module!=='undefined')module.exports=root.HUD;\n})(globalThis);\n", "let items=[],groups=[],filename='',selected=new Set(),annotations={};\nlet colors={EB_H:'#d97706',EB_N:'#126dbe',EB_L:'#008577',nominal:'#d13c61',outer:'#8048b5'};\nconst labels={EB_H:'Tall Eye Position',EB_N:'Nominal Eye Position',EB_L:'Short Eye Position'},order=['EB_H','EB_N','EB_L'];\nconst $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&\u003c>\"']/g,c=>({'&':'&amp;','\u003c':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),fmt=n=>Number.isFinite(n)?Number(n.toFixed(4)).toString():'—';\nfunction download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}\nfunction setup(){groups=HUD.groupItems(items);$('#filename').textContent=filename;$('#error').textContent='';$('#colors').innerHTML=Object.entries(colors).map(([key,color])=>`\u003clabel>${esc(labels[key]||(key==='nominal'?'中眼位公差':'高/低眼位公差'))} \u003cinput type=\"color\" data-color=\"${key}\" value=\"${color}\">\u003c/label>`).join('');$('#choices').innerHTML=groups.map((g,i)=>`\u003clabel>\u003cinput type=\"checkbox\" data-group=\"${i}\" ${selected.has(g.key)?'checked':''}> ${esc(g.name)}\u003c/label>`).join('');for(const id of ['csv','report','print'])$('#'+id).disabled=false;render();}\nfunction load(sheets,name){const parsed=HUD.parseSheets(sheets);if(!parsed.length)throw Error('未找到数据：请使用首列 Item、首行为样品编号的检测表。');items=parsed;annotations={};filename=name;selected=new Set(HUD.groupItems(items).filter(g=>g.primary).map(g=>g.key));$('#search').value='';$('#status').value='';setup();}\nfunction callout(g,id,text,color,px,py,width=165){\n const saved=annotations[g.key]?.[id],a=saved||{x:px,y:py};\n return `\u003cg class=\"annotation\" data-label=\"${esc(id)}\" data-width=\"${width}\" transform=\"translate(${a.x},${a.y})\" style=\"cursor:move;touch-action:none\">\u003ctitle>Drag to reposition\u003c/title>\u003crect width=\"${width}\" height=\"25\" rx=\"4\" fill=\"white\" fill-opacity=\".94\" stroke=\"${color}\"/>\u003ctext x=\"8\" y=\"17\" style=\"font:12px system-ui;fill:${color};pointer-events:none\">${esc(text)}\u003c/text>\u003c/g>`;\n}\nfunction chart(g){\n const series=[...g.series].sort((a,b)=>order.indexOf(a.sheet)-order.indexOf(b.sheet));\n const ids=[...new Set(series.flatMap(s=>s.points.map(p=>p.id)))];\n const vals=series.flatMap(s=>[...s.points.map(p=>p.v),s.lo,s.hi].filter(v=>v!==null));\n let min=Math.min(...vals),max=Math.max(...vals),pad=(max-min)*.13||Math.max(.1,Math.abs(max)*.1);min-=pad;max+=pad;\n const W=1100,H=590,L=80,R=190,T=110,B=200,w=W-L-R,h=H-T-B,x=i=>L+(ids.length===1?w/2:i/(ids.length-1)*w),y=v=>T+h-(v-min)/(max-min)*h;\n let svg=`\u003csvg xmlns=\"http://www.w3.org/2000/svg\" class=\"chart\" style=\"font:11px Arial,sans-serif\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(g.name)} Three Eye Positions\">\u003crect width=\"${W}\" height=\"${H}\" fill=\"white\"/>\u003ctext x=\"${L}\" y=\"26\" style=\"font: bold 19px system-ui;fill:#182b43\">${esc(g.name)} · Three Eye Positions\u003c/text>\u003ctext x=\"${L}\" y=\"48\" style=\"font:11px system-ui;fill:#64748b\">${esc(filename)} · Unit: ${esc(g.unit)} · X-axis: Sample ID\u003c/text>`;\n series.forEach((s,i)=>{const col=colors[s.sheet]||'#555',lx=L+i*260;svg+=`\u003cpath d=\"M${lx},72h32\" stroke=\"${col}\" stroke-width=\"3\"/>\u003ctext x=\"${lx+40}\" y=\"76\" style=\"fill:${col}\">${esc(labels[s.sheet]||s.sheet)}\u003c/text>`;});\n const limits=[];series.forEach(s=>{for(const [v,side]of [[s.lo,'LSL'],[s.hi,'USL']])if(v!==null)limits.push({v,side,sheet:s.sheet});});\n for(let i=0;i\u003c=5;i++){const v=min+(max-min)*i/5;svg+=`\u003cpath d=\"M${L},${y(v)}H${W-R}\" stroke=\"#e3eaf1\"/>\u003ctext x=\"${L-10}\" y=\"${y(v)+4}\" text-anchor=\"end\">${fmt(v)}\u003c/text>`;}\n // One line per limit value and tolerance family; preserve both styles when limits overlap.\n const unique=new Map();for(const a of limits){const family=a.sheet==='EB_N'?'nominal':'outer',key=family+'|'+a.v;if(!unique.has(key))unique.set(key,{...a,family,sheets:[]});unique.get(key).sheets.push(a.sheet);}\n const byValue=new Map();for(const a of unique.values()){if(!byValue.has(a.v))byValue.set(a.v,[]);byValue.get(a.v).push(a);}\n for(const [v,ls]of byValue){ls.forEach((a,i)=>{const c=colors[a.family],dash=a.family==='nominal'?'14 8':'4 5',offset=a.family==='outer'&&ls.length>1?'14':'0';svg+=`\u003cpath data-family=\"${a.family}\" d=\"M${L},${y(v)}H${W-R}\" stroke=\"${c}\" stroke-width=\"2\" stroke-dasharray=\"${dash}\" stroke-dashoffset=\"${offset}\"/>${callout(g,'limit-'+a.family+'-'+a.side+'-'+v,a.sheets.map(s=>s==='EB_N'?'Nominal':s==='EB_H'?'Tall':s==='EB_L'?'Short':s).join('/')+' '+a.side+' '+fmt(v),c,W-R+8,y(v)+(i-(ls.length-1)/2)*28-12,175)}`;});}\n series.forEach(s=>{const col=colors[s.sheet]||'#555',points=new Map(s.points.map(p=>[p.id,p]));let path='',last=false;ids.forEach((id,i)=>{const p=points.get(id);if(!p){last=false;return;}path+=(last?'L':'M')+x(i)+','+y(p.v);last=true;});svg+=`\u003cpath d=\"${path}\" fill=\"none\" stroke=\"${col}\" stroke-width=\"2\"/>`;s.points.forEach(p=>{const bad=(s.lo!==null&&p.v\u003cs.lo)||(s.hi!==null&&p.v>s.hi);svg+=`\u003ccircle cx=\"${x(ids.indexOf(p.id))}\" cy=\"${y(p.v)}\" r=\"${bad?5:3.5}\" fill=\"${col}\" stroke=\"${bad?'#e11d48':'white'}\" stroke-width=\"${bad?2:1}\">\u003ctitle>${esc(labels[s.sheet]||s.sheet)} / ${esc(p.id)}：${p.v} ${esc(g.unit)}${bad?' Out of spec':''}\u003c/title>\u003c/circle>`;});});\n ids.forEach((id,i)=>{if(i===0||i===ids.length-1||i%Math.max(1,Math.ceil(ids.length/12))===0)svg+=`\u003ctext x=\"${x(i)}\" y=\"${H-B+24}\" text-anchor=\"middle\">${esc(id)}\u003c/text>`;});\n const hasN=limits.some(a=>a.sheet==='EB_N'),hasO=limits.some(a=>a.sheet!=='EB_N');let lx=L;\n for(const [show,col,dash,label]of [[hasN,colors.nominal,'14 8','Nominal limits (long dash)'],[hasO,colors.outer,'4 5','Tall / Short limits (short dash)']])if(show){svg+=`\u003cpath d=\"M${lx},${H-B+62}h40\" stroke=\"${col}\" stroke-width=\"2\" stroke-dasharray=\"${dash}\"/>\u003ctext x=\"${lx+48}\" y=\"${H-B+66}\">${label}\u003c/text>`;lx+=310;}\n series.forEach((s,i)=>{\n  const p=s.points[Math.floor(s.points.length*(i+1)/4)],cx=x(ids.indexOf(p.id)),cy=y(p.v),col=colors[s.sheet]||'#555';\n  const pos=annotations[g.key]?.['curve-'+s.sheet]||{x:Math.max(L,Math.min(W-175,cx-70)),y:Math.max(T,Math.min(T+h-25,cy-50-i*15))};\n  svg+=`\u003cpath data-leader=\"curve-${s.sheet}\" data-ax=\"${cx}\" data-ay=\"${cy}\" d=\"M${cx},${cy}L${pos.x+82},${pos.y+25}\" stroke=\"${col}\" stroke-width=\"1\" opacity=\".7\" fill=\"none\"/>`;\n  svg+=callout(g,'curve-'+s.sheet,labels[s.sheet]||s.sheet,col,pos.x,pos.y);\n  const st=HUD.stats(s),sx=L+i*310,sy=H-112;\n  svg+=`\u003crect x=\"${sx}\" y=\"${sy}\" width=\"300\" height=\"90\" rx=\"5\" fill=\"#f5f8fc\"/>\u003ctext x=\"${sx+10}\" y=\"${sy+19}\" style=\"font:bold 13px system-ui;fill:${col}\">${esc(labels[s.sheet]||s.sheet)}\u003c/text>\u003ctext x=\"${sx+10}\" y=\"${sy+38}\" style=\"fill:${col}\">N=${st.n} · Mean: ${fmt(st.mean)}\u003c/text>\u003ctext x=\"${sx+10}\" y=\"${sy+56}\" style=\"fill:${col}\">Min: ${fmt(st.min)} / Max: ${fmt(st.max)}\u003c/text>\u003ctext x=\"${sx+10}\" y=\"${sy+74}\" style=\"font:10px system-ui;fill:${col}\">SD: ${fmt(st.sd)} · OOS: ${st.specified?st.bad.length:'N/A'} · Pass: ${st.pass===null?'N/A':(st.pass*100).toFixed(1)+'%'}\u003c/text>`;\n });\n return svg+`\u003ctext x=\"${L}\" y=\"${H-5}\" style=\"font:10px system-ui;fill:#64748b\">Screening against configured limits only; not full CG3552 compliance. SD: sample standard deviation. OOS: out of specification.\u003c/text>\u003cpath d=\"M${L},${T}V${T+h}H${W-R}\" stroke=\"#aab9c9\" fill=\"none\"/>\u003c/svg>`;\n}\nfunction visibleGroups(){const q=$('#search').value.trim().toLowerCase().replace('重影','ghost').replace('旋转','rotation').replace('尺寸','image size'),status=$('#status').value;return groups.filter(g=>{const ss=g.series.map(HUD.stats);return selected.has(g.key)&&g.name.toLowerCase().includes(q)&&(!status||(status==='bad'&&ss.some(s=>s.bad.length))||(status==='unknown'&&ss.some(s=>!s.specified))||(status==='ok'&&ss.every(s=>s.specified&&!s.bad.length)));});}\nfunction render(){const specified=items.filter(x=>HUD.stats(x).specified),bad=specified.filter(x=>HUD.stats(x).bad.length);$('#metrics').innerHTML=[['有效样品编号',new Set(items.flatMap(x=>x.points.map(p=>p.id))).size],['合并图 / 眼位测量项',groups.length+' / '+items.length],['超差项 / 已设限值',bad.length+' / '+specified.length],['待补限值测量项',items.length-specified.length]].map(([k,v])=>`\u003cdiv class=\"metric\">\u003cspan>${k}\u003c/span>\u003cstrong>${v}\u003c/strong>\u003c/div>`).join('');const visible=visibleGroups();$('#empty').classList.toggle('hidden',items.length>0);$('#count').textContent=`已选 ${selected.size} 项，当前显示 ${visible.length} 张合并图`;\n $('#cards').innerHTML=visible.map(g=>{const ss=g.series.map(HUD.stats),bad=ss.reduce((n,s)=>n+s.bad.length,0),unknown=ss.some(s=>!s.specified);return `\u003carticle class=\"card\" data-g=\"${groups.indexOf(g)}\">\u003cdiv class=\"cardtop\">\u003ch3>${esc(g.name)}\u003c/h3>\u003cspan class=\"badge ${bad?'bad':unknown?'':'ok'}\">${bad?'Out of spec: '+bad:unknown?'Limits not fully specified':'Within configured limits'}\u003c/span>\u003c/div>${chart(g)}\u003cdiv class=\"seriesstats\">${g.series.map(s=>{const st=HUD.stats(s);return `\u003cdiv class=\"stats\">\u003cspan style=\"color:${colors[s.sheet]||'#555'}\">\u003cb>${esc(labels[s.sheet]||s.sheet)}\u003c/b>N=${st.n} · Mean: ${fmt(st.mean)}\u003cbr>Min: ${fmt(st.min)} / Max: ${fmt(st.max)}\u003cbr>SD: ${fmt(st.sd)} · OOS: ${st.specified?st.bad.length:'N/A'} · Pass rate: ${st.pass===null?'N/A':(st.pass*100).toFixed(1)+'%'}\u003c/span>\u003c/div>`;}).join('')}\u003c/div>${order.filter(s=>!g.series.some(i=>i.sheet===s)).map(s=>`\u003cp class=\"note\">${labels[s]}：无此项目数据，未补零或推算。\u003c/p>`).join('')}\u003cdetails>\u003csummary>调整各眼位公差 / 查看判定依据\u003c/summary>${g.series.map(s=>`\u003cdiv class=\"limits\" data-i=\"${items.indexOf(s)}\">\u003cb>${esc(labels[s.sheet]||s.sheet)}\u003c/b>\u003clabel>下限 \u003cinput aria-label=\"下限\" type=\"number\" step=\"any\" class=\"lo\" value=\"${s.lo??''}\">\u003c/label>\u003clabel>上限 \u003cinput aria-label=\"上限\" type=\"number\" step=\"any\" class=\"hi\" value=\"${s.hi??''}\">\u003c/label>\u003cbutton class=\"secondary apply\">应用\u003c/button>\u003c/div>\u003cp class=\"note\">${esc(s.source)}；${esc(s.note)}\u003c/p>`).join('')}\u003c/details>\u003cp class=\"note\">Drag the colored curve labels or limit labels to reposition. Export preserves label positions and includes English statistics.\u003c/p>\u003cdiv class=\"actions\">\u003cbutton class=\"secondary reset-labels\">重置标注 / Reset labels\u003c/button>\u003cbutton class=\"secondary svg\">导出合并 SVG\u003c/button>\u003cbutton class=\"secondary png\">导出合并 PNG\u003c/button>\u003c/div>\u003cdetails>\u003csummary>各眼位样品数据与超差明细\u003c/summary>\u003cdiv class=\"scroll\">\u003ctable>\u003ctr>\u003cth>眼位\u003c/th>\u003cth>样品\u003c/th>\u003cth>数值 (${esc(g.unit)})\u003c/th>\u003cth>判定\u003c/th>\u003c/tr>${g.series.flatMap(s=>s.points.map(p=>{const st=HUD.stats(s),b=st.bad.includes(p);return `\u003ctr>\u003ctd>${esc(labels[s.sheet]||s.sheet)}\u003c/td>\u003ctd>${esc(p.id)}\u003c/td>\u003ctd>${p.v}\u003c/td>\u003ctd>${!st.specified?'未判定':b?'超差':'限值内'}\u003c/td>\u003c/tr>`;})).join('')}\u003c/table>\u003c/div>\u003c/details>\u003c/article>`;}).join('')|| (items.length?'\u003cdiv class=\"panel\">没有符合当前勾选或筛选条件的项目，请调整选择。\u003c/div>':'');}\n$('#colors').oninput=e=>{if(e.target.dataset.color){colors[e.target.dataset.color]=e.target.value;render();}};\n$('#choices').onchange=e=>{if(e.target.dataset.group!==undefined){const key=groups[Number(e.target.dataset.group)].key;if(e.target.checked)selected.add(key);else selected.delete(key);render();}};\n$('#search').oninput=render;$('#status').onchange=render;\n$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const book=XLSX.read(await f.arrayBuffer(),{type:'array'}),sheets={};book.SheetNames.forEach(n=>sheets[n]=XLSX.utils.sheet_to_json(book.Sheets[n],{header:1,defval:null,raw:true,blankrows:false}));load(sheets,f.name);}catch(err){$('#error').textContent='读取失败：'+err.message;}finally{e.target.value='';}};\n$('#demo').onclick=()=>load(window.HUD_DEMO,'L232 HUD Inspective dates 20261110.xlsx');\n$('#cards').onclick=async e=>{const card=e.target.closest('.card');if(!card)return;const g=groups[Number(card.dataset.g)];if(e.target.closest('.reset-labels')){delete annotations[g.key];render();return;}if(e.target.closest('.apply')){const row=e.target.closest('.limits'),item=items[Number(row.dataset.i)];let lo=row.querySelector('.lo').value,hi=row.querySelector('.hi').value;lo=lo===''?null:Number(lo);hi=hi===''?null:Number(hi);if((lo!==null&&!Number.isFinite(lo))||(hi!==null&&!Number.isFinite(hi))||(lo!==null&&hi!==null&&lo>hi)){alert('下限不能大于上限，请输入有效数值');return;}Object.assign(item,{lo,hi,source:'用户手动设置，请核对客户批准值'});render();}\n if(e.target.closest('.svg')||e.target.closest('.png')){const blob=new Blob([chart(g)],{type:'image/svg+xml;charset=utf-8'}),name=g.name.replace(/[\\\\/:*?\"\u003c>|]/g,'_')+'_三眼位';if(e.target.closest('.svg'))download(blob,name+'.svg');else{const u=URL.createObjectURL(blob),img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=2200;c.height=1180;c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(b=>download(b,name+'.png'));URL.revokeObjectURL(u);};img.src=u;}}};\nfunction csvCell(v){let t=String(v??'');if(/^[=+@-]/.test(t)&&!Number.isFinite(Number(t)))t=\"'\"+t;return '\"'+t.replace(/\"/g,'\"\"')+'\"';}\n$('#csv').onclick=()=>{const rows=[['文件','眼位','项目','单位','下限','上限','N','均值','最小','最大','样本标准差','超差数','合格率','超差样品','依据','说明']];visibleGroups().forEach(g=>g.series.forEach(x=>{const s=HUD.stats(x);rows.push([filename,x.sheet,x.name,x.unit,x.lo,x.hi,s.n,s.mean,s.min,s.max,s.sd,s.specified?s.bad.length:'未判定',s.pass===null?'未判定':(s.pass*100).toFixed(2)+'%',s.bad.map(p=>p.id+':'+p.v).join(';'),x.source,x.note]);}));download(new Blob(['\\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\\r\\n')],{type:'text/csv;charset=utf-8'}),'HUD所选项目汇总.csv');};\n$('#print').onclick=()=>window.print();\n$('#report').onclick=()=>{const doc=document.documentElement.cloneNode(true);doc.querySelectorAll('script').forEach(s=>s.remove());const state=JSON.stringify({items,filename,colors,annotations,selected:[...selected],search:$('#search').value,status:$('#status').value}).replace(/\u003c/g,'\\\\u003c');const boot=document.createElement('script');boot.textContent='window.HUD_REPORT='+state+';window.HUD_BUNDLE='+JSON.stringify(window.HUD_BUNDLE).replace(/\u003c/g,'\\\\u003c')+';';doc.querySelector('body').appendChild(boot);for(const source of window.HUD_BUNDLE){const s=document.createElement('script');s.textContent=source;doc.querySelector('body').appendChild(s);}download(new Blob(['\u003c!doctype html>'+doc.outerHTML],{type:'text/html;charset=utf-8'}),'HUD三眼位交互报告.html');};\nif(window.HUD_REPORT){({items,filename,colors}=window.HUD_REPORT);annotations=window.HUD_REPORT.annotations||{};selected=new Set(window.HUD_REPORT.selected);$('#search').value=window.HUD_REPORT.search||'';$('#status').value=window.HUD_REPORT.status||'';$('#demo').disabled=true;$('#file').disabled=true;setup();}\n\nlet drag=null;\n$('#cards').addEventListener('pointerdown',e=>{\n const label=e.target.closest('.annotation');if(!label)return;\n const svg=label.ownerSVGElement,card=label.closest('.card'),g=groups[Number(card.dataset.g)],matrix=svg.getScreenCTM();if(!matrix)return;\n const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()),t=label.transform.baseVal.getItem(0).matrix;\n drag={label,svg,key:g.key,id:label.dataset.label,dx:p.x-t.e,dy:p.y-t.f,width:Number(label.dataset.width)};\n label.setPointerCapture(e.pointerId);e.preventDefault();\n});\n$('#cards').addEventListener('pointermove',e=>{\n if(!drag)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(drag.svg.getScreenCTM().inverse());\n const x=Math.max(0,Math.min(1100-drag.width,p.x-drag.dx)),y=Math.max(0,Math.min(590-25,p.y-drag.dy));\n drag.label.setAttribute('transform',`translate(${x},${y})`);const leader=drag.svg.querySelector(`[data-leader=\"${drag.id}\"]`);if(leader)leader.setAttribute('d',`M${leader.dataset.ax},${leader.dataset.ay}L${x+82},${y+25}`);annotations[drag.key]??={};annotations[drag.key][drag.id]={x,y};\n});\nfor(const event of ['pointerup','pointercancel','lostpointercapture'])$('#cards').addEventListener(event,()=>{drag=null;});\n"];